class Solution {
    public int matrixScore(int[][] grid){
        int rows=grid.length,columns=grid[0].length,answer=0;
        for(int c=0;c<columns;c++){
            int ones=0;
            for(int r=0;r<rows;r++)if((grid[r][c]^grid[r][0])==0)ones++;
            ones=Math.max(ones,rows-ones);
            answer+=ones*(1<<(columns-1-c));
        }
        return answer;
    }
}

